Bj10eGlyph get_bj10e_glyph(uint8_t ch, bool cp850, bool secondary,
                           bool proportional)
{
	if (proportional) {
		return cp850 ? Bj10eGlyph{bj10e_cp850_prop[ch], bj10e_cp850_prop_width[ch]}
		             : Bj10eGlyph{bj10e_cp437_prop[ch], bj10e_cp437_prop_width[ch]};
	}
	if (secondary)
		return cp850 ? Bj10eGlyph{bj10e_cp850_secondary[ch], 30}
		             : Bj10eGlyph{bj10e_cp437_secondary[ch], 30};
	return cp850 ? Bj10eGlyph{bj10e_cp850_primary[ch], 36}
	             : Bj10eGlyph{bj10e_cp437_primary[ch], 36};
}
